const titles = [
  { query: 'registered nurse', categoryHint: 'healthcare' },
  { query: 'clinical officer', categoryHint: 'healthcare' },
  { query: 'primary school teacher', categoryHint: 'education' },
  { query: 'secondary school teacher', categoryHint: 'education' },
  { query: 'social worker', categoryHint: 'social-work' },
  { query: 'hotel receptionist', categoryHint: 'hospitality' },
  { query: 'warehouse supervisor', categoryHint: 'logistics' },
  { query: 'civil engineer', categoryHint: 'construction-trades' },
  { query: 'electrician', categoryHint: 'skilled-trades' },
  { query: 'accountant', categoryHint: 'finance' },
  { query: 'software engineer', categoryHint: 'software-development' },
  { query: 'farm manager', categoryHint: 'agriculture' },
  { query: 'sales executive', categoryHint: 'sales' },
  { query: 'human resource officer', categoryHint: 'human-resources' }
];
const locations = ['Kenya', 'Nairobi', 'Mombasa', 'Kisumu', 'Nakuru', 'Eldoret'];
const items = [];
for (const t of titles) {
  for (const loc of locations) {
    items.push({ json: { ...t, location: loc, searchQuery: `${t.query} jobs in ${loc}` } });
  }
}
return items;

// Light client-side preprocess (server also validates)
const BLOCKED = new Set(['example.com','example.org','example.net','www.example.com','www.example.org','www.example.net']);
const item = $input.first().json;
const title = String(item.title || item.query || '').trim();
const company = String(item.company_name || item.company || '').trim();
let url = String(item.external_link || item.url || '').trim();
if (!title || !company || !url) return [];
try {
  const u = new URL(url.startsWith('http') ? url : 'https://' + url);
  const host = u.hostname.toLowerCase();
  if (BLOCKED.has(host) || host.endsWith('.example.com')) return [];
  ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid'].forEach(k => u.searchParams.delete(k));
  url = u.toString();
} catch (e) { return []; }
return [{
  json: {
    title: title.slice(0, 255),
    company_name: company.slice(0, 255),
    external_link: url,
    location: item.location || 'Not specified',
    description: String(item.description || title).slice(0, 50000),
    job_type: item.job_type || 'onsite',
    category: item.category || item.categoryHint || undefined,
    source: 'n8n-google'
  }
}];
